import React from 'react';
import {
  Alert,
  Autocomplete,
  Box,
  Button,
  Chip,
  CircularProgress,
  IconButton,
  InputAdornment,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import MyLocationRounded from '@mui/icons-material/MyLocationRounded';
import PlaceRounded from '@mui/icons-material/PlaceRounded';
import SwapHorizRounded from '@mui/icons-material/SwapHorizRounded';
import SearchRounded from '@mui/icons-material/SearchRounded';
import { alpha, useTheme } from '@mui/material/styles';

import { DEMO_LOCATIONS, DEMO_PRESETS } from '../theme/webTheme';

function renderField(theme, label, placeholder, value, onChange, icon, onSearch) {
  return (
    <Autocomplete
      freeSolo
      options={DEMO_LOCATIONS}
      value={value}
      onChange={(_, nextValue) => onChange(nextValue || '')}
      onInputChange={(_, nextValue) => onChange(nextValue || '')}
      renderInput={(params) => (
        <TextField
          {...params}
          label={label}
          placeholder={placeholder}
          onKeyDown={(event) => {
            if (event.key === 'Enter') {
              event.preventDefault();
              onSearch();
            }
          }}
          InputProps={{
            ...params.InputProps,
            startAdornment: (
              <InputAdornment position="start">
                {icon}
              </InputAdornment>
            ),
          }}
          sx={{
            '& .MuiOutlinedInput-root': {
              borderRadius: 2.5,
              backgroundColor:
                theme.palette.mode === 'dark'
                  ? alpha('#0F172A', 0.6)
                  : alpha('#FFFFFF', 0.9),
              '& fieldset': {
                borderColor:
                  theme.palette.mode === 'dark'
                    ? alpha('#475569', 0.3)
                    : alpha('#CBD5E1', 0.5),
              },
              '&:hover fieldset': {
                borderColor: alpha('#3B82F6', 0.5),
              },
              '&.Mui-focused fieldset': {
                borderColor: '#3B82F6',
                boxShadow: `0 0 0 3px ${alpha('#3B82F6', 0.15)}`,
              },
            },
          }}
        />
      )}
    />
  );
}

export default function SearchInput({
  source,
  destination,
  onSourceChange,
  onDestinationChange,
  onSearch,
  onSwap,
  loading,
  statusMessage,
}) {
  const theme = useTheme();

  return (
    <Stack spacing={2.5}>
      <Stack direction={{ xs: 'column', xl: 'row' }} spacing={1.5} alignItems="stretch">
        <Box sx={{ flex: 1 }}>
          {renderField(
            theme,
            'From',
            'Enter starting point',
            source,
            onSourceChange,
            <MyLocationRounded sx={{ color: '#3B82F6', fontSize: 22 }} />,
            onSearch
          )}
        </Box>

        <Stack direction="row" spacing={1.5} sx={{ flex: 1, alignItems: 'stretch' }}>
          <Box sx={{ flex: 1 }}>
            {renderField(
              theme,
              'To',
              'Enter destination',
              destination,
              onDestinationChange,
              <PlaceRounded sx={{ color: '#EF4444', fontSize: 22 }} />,
              onSearch
            )}
          </Box>

          <IconButton
            onClick={onSwap}
            sx={{
              alignSelf: 'center',
              width: 48,
              height: 48,
              borderRadius: '14px',
              border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
              backgroundColor: theme.palette.mode === 'dark' ? alpha('#1E293B', 0.6) : alpha('#FFFFFF', 0.9),
              color: theme.palette.text.secondary,
              flexShrink: 0,
              '&:hover': {
                backgroundColor: theme.palette.mode === 'dark' ? alpha('#334155', 0.8) : alpha('#F1F5F9', 0.95),
                color: theme.palette.text.primary,
                transform: 'rotate(180deg)',
              },
              transition: 'all 200ms ease',
            }}
          >
            <SwapHorizRounded />
          </IconButton>

          <Button
            onClick={onSearch}
            disabled={loading}
            variant="contained"
            startIcon={loading ? <CircularProgress size={18} sx={{ color: '#FFFFFF' }} /> : <SearchRounded />}
            sx={{
              minWidth: { xs: '100%', xl: 200 },
              alignSelf: 'stretch',
              background: 'linear-gradient(135deg, #1D4ED8 0%, #3B82F6 100%)',
              boxShadow: '0 4px 14px rgba(59, 130, 246, 0.35)',
              fontWeight: 700,
              fontSize: '0.95rem',
              borderRadius: '14px',
              textTransform: 'none',
              '&:hover': {
                background: 'linear-gradient(135deg, #1E40AF 0%, #2563EB 100%)',
                boxShadow: '0 6px 20px rgba(59, 130, 246, 0.45)',
                transform: 'translateY(-1px)',
              },
              '&:disabled': {
                background: alpha('#64748B', 0.6),
              },
              transition: 'all 200ms ease',
            }}
          >
            {loading ? 'Analyzing...' : 'Find Routes'}
          </Button>
        </Stack>
      </Stack>

      <Stack direction="row" spacing={1} flexWrap="wrap" alignItems="center">
        <Typography variant="caption" sx={{ color: 'text.secondary', mr: 1 }}>
          Try:
        </Typography>
        {DEMO_PRESETS.map((preset) => (
          <Chip
            key={preset.label}
            label={preset.label}
            onClick={() => {
              onSourceChange(preset.source);
              onDestinationChange(preset.destination);
            }}
            size="small"
            sx={{
              fontSize: '0.75rem',
              height: 28,
              border: `1px solid ${alpha(theme.palette.primary.main, 0.2)}`,
              backgroundColor: 'transparent',
              color: theme.palette.primary.main,
              '&:hover': {
                backgroundColor: alpha(theme.palette.primary.main, 0.1),
                borderColor: theme.palette.primary.main,
              },
            }}
          />
        ))}
      </Stack>

      {statusMessage ? (
        <Alert
          severity={statusMessage.severity || 'info'}
          sx={{
            borderRadius: 2,
            fontSize: '0.875rem',
            backgroundColor: statusMessage.severity === 'success' 
              ? alpha('#10B981', 0.1)
              : statusMessage.severity === 'error'
              ? alpha('#EF4444', 0.1)
              : statusMessage.severity === 'warning'
              ? alpha('#F59E0B', 0.1)
              : alpha(theme.palette.primary.main, 0.1),
            border: `1px solid ${
              statusMessage.severity === 'success' 
                ? alpha('#10B981', 0.3)
                : statusMessage.severity === 'error'
                ? alpha('#EF4444', 0.3)
                : statusMessage.severity === 'warning'
                ? alpha('#F59E0B', 0.3)
                : alpha(theme.palette.primary.main, 0.2)
            }`,
          }}
        >
          {statusMessage.text}
        </Alert>
      ) : null}
    </Stack>
  );
}
